/**
 * A brand's mark, the only place one is drawn and the one place colour other
 * than the tokens appears: the brand's official logo in its own colours, never
 * tinted by the text colour, so a dimmed row dims it with opacity.
 * - Vector marks are inline paths, so nothing is fetched to draw them. The
 *   one-colour ones are Simple Icons (CC0, simple-icons@16.37.0) filled with
 *   its brand hex; Google, Gmail and Drive are the brands' own multi-colour
 *   logos; OpenAI's is the logomark its own site serves.
 * - A brand Simple Icons lacks is its own app icon, served from
 *   `public/brands/` (sources in `SOURCES.md` there), square with a 3px
 *   radius. Never hotlinked: the app runs offline.
 */
export type Brand =
  | 'google'
  | 'box'
  | 'airtable'
  | 'gmail'
  | 'apollo'
  | 'exa'
  | 'granola'
  | 'anthropic'
  | 'openai'
  | 'openrouter'
  | 'ollama'
  | 'googleCalendar'
  | 'googleDrive'

type Mark =
  | {
      readonly kind: 'vector'
      readonly viewBox: string
      /** Each path's fill and its data, painted in order. */
      readonly paths: ReadonlyArray<readonly [fill: string, d: string]>
    }
  | { readonly kind: 'icon'; readonly src: string }

